const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Approximate location for Digangali, Chad (near Lake Chad). Adjust if exact coords are known.
  const point = ee.Geometry.Point([14.6, 13.25]); // lon, lat
  const aoi = point.buffer(5000); // 5 km buffer

  const date1Str = '2021-09-18';
  const date2Str = '2022-10-23';
  const winDaysPrimary = 14;
  const winDaysFallback = 30;
  const scale = 1000; // to avoid timeouts per best practice

  // 2. Helper functions
  function maskS2sr(img) {
    const scl = img.select('SCL');
    const mask = scl.neq(3) // cloud shadow
      .and(scl.neq(8)) // clouds
      .and(scl.neq(9)) // high-prob clouds
      .and(scl.neq(10)) // thin cirrus
      .and(scl.neq(1)) // saturated/defective
      .and(scl.neq(7)) // unclassified
      .and(scl.neq(0)); // no data
    return img.updateMask(mask);
  }

  async function getS2WaterStats(aoi, centerDateStr, daysWindow) {
    const center = ee.Date(centerDateStr);
    const start = center.advance(-daysWindow, 'day');
    const end = center.advance(daysWindow + 1, 'day');
    let col = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(aoi)
      .filterDate(start, end)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
    const n = await col.size().getInfo();
    if (n === 0) return { status: 'empty', src: 'S2', nImages: 0 };

    const cloudMean = await col.aggregate_mean('CLOUDY_PIXEL_PERCENTAGE').getInfo();
    const masked = col.map(maskS2sr);
    const composite = masked.median();
    const mndwi = composite.expression('(G - S) / (G + S)', {
      'G': composite.select('B3'),
      'S': composite.select('B11')
    }).rename('MNDWI');

    const validCount = await mndwi.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9,
    }).get('MNDWI').getInfo();

    if (!validCount || validCount === 0) {
      return { status: 'noValid', src: 'S2', nImages: n, cloudMean: cloudMean, validPix: 0, waterKm2: 0 };
    }

    const waterMask = mndwi.gt(0.1);
    const waterArea = await ee.Image.pixelArea().updateMask(waterMask).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9,
    }).get('area').getInfo();

    const waterKm2 = (waterArea || 0) / 1e6;
    return { status: 'ok', src: 'S2', nImages: n, cloudMean: cloudMean, validPix: validCount, waterKm2: waterKm2 };
  }

  async function getS1WaterStats(aoi, centerDateStr, daysWindow) {
    const center = ee.Date(centerDateStr);
    const start = center.advance(-daysWindow, 'day');
    const end = center.advance(daysWindow + 1, 'day');
    let col = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(aoi)
      .filterDate(start, end)
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.eq('resolution_meters', 10))
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VH'))
      .filter(ee.Filter.eq('orbitProperties_pass', 'DESCENDING'))
      .select(['VV', 'VH']);
    const n = await col.size().getInfo();
    if (n === 0) return { status: 'empty', src: 'S1', nImages: 0 };

    const med = col.median();
    const vv = med.select('VV').add(1e-6);
    const vh = med.select('VH').add(1e-6);
    const vvDb = vv.log10().multiply(10);
    const vhDb = vh.log10().multiply(10);

    // Water tends to be very dark in both bands
    const waterMask = vvDb.lt(-16).and(vhDb.lt(-24));
    const validCount = await vvDb.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9,
    }).get('VV').getInfo();

    if (!validCount || validCount === 0) {
      return { status: 'noValid', src: 'S1', nImages: n, cloudMean: null, validPix: 0, waterKm2: 0 };
    }

    const waterArea = await ee.Image.pixelArea().updateMask(waterMask).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9,
    }).get('area').getInfo();

    const waterKm2 = (waterArea || 0) / 1e6;
    return { status: 'ok', src: 'S1', nImages: n, cloudMean: null, validPix: validCount, waterKm2: waterKm2 };
  }

  async function getWaterStatsWithFallback(aoi, centerDateStr) {
    // Try S2 with primary window
    let res = await getS2WaterStats(aoi, centerDateStr, winDaysPrimary);
    if (res.status === 'empty') {
      // Widen S2 window
      res = await getS2WaterStats(aoi, centerDateStr, winDaysFallback);
    }
    if (res.status === 'noValid' || res.status === 'empty') {
      // Fallback to S1 primary
      res = await getS1WaterStats(aoi, centerDateStr, winDaysPrimary);
      if (res.status === 'empty') {
        // Widen S1 window
        res = await getS1WaterStats(aoi, centerDateStr, winDaysFallback);
      }
    }
    return res;
  }

  function isInvalidNumber(x) {
    return x === null || x === undefined || isNaN(x) || !isFinite(x);
  }

  // 3. Run processing for both dates
  try {
    console.log(`AOI center (lat,lon): (13.25, 14.60), buffer_m: 5000`);

    const res1 = await getWaterStatsWithFallback(aoi, date1Str);
    if (res1.status === 'empty') {
      console.log(`${date1Str} Data: 0 images`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      console.log('C1');
      return;
    }
    if (res1.status === 'noValid') {
      console.log(`${date1Str} ${res1.src}: imgs=${res1.nImages}, validPix=0`);
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      console.log('C2');
      return;
    }
    if (isInvalidNumber(res1.waterKm2)) {
      console.log(`${date1Str} ${res1.src}: Calculation failure`);
      console.log('C3: Calculation Failure (Result invalid).');
      console.log('C3');
      return;
    }

    const cloud1 = res1.cloudMean !== null && res1.cloudMean !== undefined ? res1.cloudMean.toFixed(1) : 'NA';
    console.log(`${date1Str} ${res1.src}: imgs=${res1.nImages}, cloud%=${cloud1}, validPix=${res1.validPix}, water_km2=${res1.waterKm2.toFixed(2)}`);

    const res2 = await getWaterStatsWithFallback(aoi, date2Str);
    if (res2.status === 'empty') {
      console.log(`${date2Str} Data: 0 images`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      console.log('C1');
      return;
    }
    if (res2.status === 'noValid') {
      console.log(`${date2Str} ${res2.src}: imgs=${res2.nImages}, validPix=0`);
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      console.log('C2');
      return;
    }
    if (isInvalidNumber(res2.waterKm2)) {
      console.log(`${date2Str} ${res2.src}: Calculation failure`);
      console.log('C3: Calculation Failure (Result invalid).');
      console.log('C3');
      return;
    }

    const cloud2 = res2.cloudMean !== null && res2.cloudMean !== undefined ? res2.cloudMean.toFixed(1) : 'NA';
    console.log(`${date2Str} ${res2.src}: imgs=${res2.nImages}, cloud%=${cloud2}, validPix=${res2.validPix}, water_km2=${res2.waterKm2.toFixed(2)}`);

    const diff = res2.waterKm2 - res1.waterKm2;
    console.log(`Difference_km2: ${(diff).toFixed(2)}`);

    if (isInvalidNumber(diff)) {
      console.log('C3: Calculation Failure (Result invalid).');
      console.log('C3');
      return;
    }

    const tol = 0.01; // km2 tolerance
    if (diff > tol) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
